parameters.jsCode:
const query = $json.query.toLowerCase();

const policyKeywords = {
  'P-01': ['loan', 'eligib'],
  'P-02': ['delinquen', 'past due'],
  'P-03': ['tenure', 'new member', 'how long'],
  'P-04': ['another member', 'cross-member', "someone else"],
  'P-05': ['restructur']
};

let matches = [];
for (const [policyId, keywords] of Object.entries(policyKeywords)) {
  if (keywords.some(kw => query.includes(kw))) {
    matches.push(policyId);
  }
}

return {
  json: {
    ...$json,
    matched_policy_ids: matches,
    policy_match_found: matches.length > 0
  }
};

const query = $json.query.toLowerCase();

const individualIndicators = ['balance', 'loan status', 'account status', 'my account', 'this account', 'this member'];
const aggregateIndicators = ['how many', 'overall', 'average', 'total members', 'aggregate', 'policy on', 'what is the policy'];

const hasIndividual = individualIndicators.some(kw => query.includes(kw));
const hasAggregate = aggregateIndicators.some(kw => query.includes(kw));

let sensitivity_level;
if (hasIndividual && !hasAggregate) {
  sensitivity_level = 'individual_detail';
} else if (hasAggregate && !hasIndividual) {
  sensitivity_level = 'aggregate_or_policy';
} else if (hasIndividual && hasAggregate) {
  sensitivity_level = 'individual_detail'; // ambiguous case defaults to the stricter classification
} else {
  sensitivity_level = 'aggregate_or_policy'; // no indicator hit defaults to the looser classification
}

return {
  json: {
    ...$json,
    sensitivity_level
  }
};

const role = $json.requester_role;
const accessLevel = $json.requester_access_level; // Frontline / Senior / BOD title, from Combine Requester + Member
const sensitivity = $json.sensitivity_level;

let ceiling_ok = true;
let ceiling_reason = '';

if (role === 'member') {
  // Members querying their own account never trip P-08 — that's P-04's territory, already enforced in Workflow 2
  ceiling_ok = true;
} else if (role === 'staff') {
  if (accessLevel === 'Frontline' && sensitivity === 'individual_detail') {
    ceiling_ok = true; // Frontline can see their own assigned members' individual detail
    ceiling_reason = 'Frontline access to assigned member individual detail permitted';
  } else if (accessLevel === 'Senior' && sensitivity === 'aggregate_or_policy') {
    ceiling_ok = true;
    ceiling_reason = 'Senior staff access to aggregate/policy data permitted';
  } else {
    ceiling_ok = true; // default permissive until specific BOD-title ceilings below are added
  }
} else if (role === 'bod') {
  if (sensitivity === 'individual_detail') {
    ceiling_ok = false;
    ceiling_reason = 'P-08: BOD role should not receive individual member financial detail unless explicitly escalated';
  } else {
    ceiling_ok = true;
  }
}

return {
  json: {
    ...$json,
    ceiling_ok,
    ceiling_reason
  }
};

