const matchedCount = $('Ceiling OK?').item.json.matched_policy_count;
const memberFound = $('Ceiling OK?').item.json.member_found;
const draftAnswer = $json.response;
const confident = (matchedCount === 1 && memberFound === true);

return {
  json: {
    ...$('Ceiling OK?').item.json,
    draft_answer: draftAnswer,
    confident: confident
  }
};
